--
-- Table structure for table `lantais`
--

DROP TABLE IF EXISTS `lantais`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lantais` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `gedung_id` bigint unsigned NOT NULL,
  `kode_lantai` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_lantai` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
