--
-- Table structure for table `log_kirim_antrians`
--

DROP TABLE IF EXISTS `log_kirim_antrians`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `log_kirim_antrians` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kodebooking` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_antrian` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sumber_antrian` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `no_registrasi` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_pendaftaran` date DEFAULT NULL,
  `nama_pasien` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `no_rm` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `no_kartu` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nik` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_poli` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_dokter` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jam_praktek` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '06:00-22:00',
  `status_kirim_antrian` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Terkirim',
  `status_kehadiran` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Terkirim',
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `task_id` int NOT NULL,
  `waktu_kirim` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `request_payload` text COLLATE utf8mb4_unicode_ci,
  `response_api` text COLLATE utf8mb4_unicode_ci,
  `status_berhasil` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=109 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

