--
-- Table structure for table `pembayaran_hutangs`
--

DROP TABLE IF EXISTS `pembayaran_hutangs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pembayaran_hutangs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `hutang_id` bigint unsigned NOT NULL,
  `nomor_bukti` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_bayar` date NOT NULL,
  `nominal_bayar` decimal(15,2) NOT NULL,
  `metode_pembayaran` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Transfer',
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pembayaran_hutangs_hutang_id_foreign` (`hutang_id`),
  CONSTRAINT `pembayaran_hutangs_hutang_id_foreign` FOREIGN KEY (`hutang_id`) REFERENCES `hutangs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

