  `waktu_panggil` time DEFAULT NULL,
  `status_antrian` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'Menunggu',
  `skrining_visual` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pasien stabil',
  `jenis_rawat` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Rawat Jalan',
