DROP TABLE IF EXISTS `tindakans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tindakans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `poliklinik_id` bigint unsigned DEFAULT NULL,
  `kode_tindakan` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_tindakan` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_konsultasi` tinyint(1) NOT NULL DEFAULT '0',
  `is_informed_consent` tinyint(1) NOT NULL DEFAULT '0',
  `is_ranap` tinyint(1) NOT NULL DEFAULT '1',
  `bhp` decimal(14,2) NOT NULL DEFAULT '0.00',
  `jasa_petugas` decimal(14,2) NOT NULL DEFAULT '0.00',
  `penyusutan_gedung` decimal(14,2) NOT NULL DEFAULT '0.00',
  `penyusutan_alat` decimal(14,2) NOT NULL DEFAULT '0.00',
  `unit_cost` decimal(14,2) NOT NULL DEFAULT '0.00',
  `kategori` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tindakans_kode_tindakan_unique` (`kode_tindakan`),
  KEY `tindakans_poliklinik_id_foreign` (`poliklinik_id`),
  CONSTRAINT `tindakans_poliklinik_id_foreign` FOREIGN KEY (`poliklinik_id`) REFERENCES `polikliniks` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
